// SellerContainer.js

import React, { useState } from "react";
import AdminOrderList from "../Orders/AdminOrderList";
import OrderDetails from "../Orders/OrderDetails";
import "./SellerContainer.scss";

const SellerContainer = () => {
  const [selectedOrder, setSelectedOrder] = useState(null);

  const handleOrderDetails = (order) => {
    setSelectedOrder(order);
  };

  const onBackClick = () => {
    setSelectedOrder(null);
  };

  return (
    <div className="seller-container">
      {selectedOrder ? (
        <div className="details-container">
          <OrderDetails orderId={selectedOrder.orderId} onBackClick={onBackClick} />
        </div>
      ) : (
        <div className="order-list-container">
          <h2>Commandes à Valider</h2>
          <AdminOrderList handleOrderDetails={handleOrderDetails} />
        </div>
      )}
    </div>
  );
};

export default SellerContainer;
